function dialDistance(bits, pairs) {
  const total = 2 ** bits;
  return pairs.map(([a, b]) => {
    let clickA = -1;
    let clickB = -1;
    for (let click = 0; click < total && (clickA < 0 || clickB < 0); click++) {
      const shown = click ^ (click >> 1);
      if (shown === a) clickA = click;
      if (shown === b) clickB = click;
    }
    const forward = (clickB - clickA + total) % total;
    return Math.min(forward, total - forward);
  });
}

function dialDistance(bits, pairs) {
  const total = 2 ** bits;
  const clickOf = (setting) => {
    let click = setting;
    click ^= click >> 1;
    click ^= click >> 2;
    click ^= click >> 4;
    click ^= click >> 8;
    click ^= click >> 16;
    return click;
  };
  return pairs.map(([a, b]) => {
    const apart = Math.abs(clickOf(a) - clickOf(b));
    return Math.min(apart, total - apart);
  });
}
